INSERT INTO departments (id, slug, name, short_description, full_description, mission, vision, values, objectives, established_date, logo_key, cover_image_key, cover_image, accent_color, stats, programs, telegram_link, telegram_chat_id, registration_status, registration_fields, requirements)
VALUES ('dept-charity', 'charity', '{"ar":"بيت الرحمة الخيرية","en":"Bayt Al-Rahma Charity","am":"ቤት አል-ራህማ በጎ አድራጎት","om":"Bayt Al-Rahma Gargaarsa"}', '{"ar":"ذراع الخير في المؤسسة: إطعام الفقراء وكفالة الأيتام ومساعدة المحتاجين","en":"The charitable arm of the institution: feeding the poor, sponsoring orphans, and helping the needy","am":"የተቋሙ የበጎ ክንፍ: ድሆችን ማበላሸፍ፣ አይሞቹን ማስተዳደር፣ ተፈላጊዎችን ርድኦ","om":"Kan gargaarsa kallattii: hiyyeeyyii nyaachisuu, abbaa irraa dhabee deggamsuu, hiyyeeyyii gargaaruu"}', '{"ar":"تأسس بيت الرحمة الخيرية عام 2014 بالتقويم الإثيوبي كذراع خيري للمؤسسة. يقدم البيت وجبة إطعام يومية لـ 82 طفلاً من الأطفال المساكين، ويوفر مساعدات رمضانية ووجبات العيد مع الأضاحي والملابس، ومواد تعليمية للعودة للمدارس، وجهود دعوية نتج عنها عودة 11 أسرة إلى الإسلام، كما قام بترميم أكثر من 7 منازل للأسر المحتاجة.","en":"Bayt Al-Rahma Charity was established in 2014 Ethiopian calendar as the charitable arm of the institution. It provides daily breakfast for 82 poor children, Ramadan aid, Eid meals with Qurbani and clothing, back-to-school educational materials, and Dawah efforts that resulted in 11 families returning to Islam. It has also renovated more than 7 homes for needy families.","am":"ቤት አል-ራህማ በ2014 የኢትዮጵያ ቀን መቁጠሪያ ተመሰረተ። ለ82 ድህከልጆች በየቀኑ ምሳ ይሰጣል።","om":"Bayt Al-Rahma Gargaarsa 2014 kabajaa Itoophiyaa kan hundeeffame. Guyyaa tokkotti ilmuu 82 nyaachisa. Maatii 11 gara Islaamaatti deebi''an. Mana 7 ol fooyya''eera."}', '{"ar":"تخفيف معاناة الفقراء والمحتاجين وإدخال الفرح إلى قلوب الأطفال والأسر المسلمة","en":"Alleviating the suffering of the poor and needy, and bringing joy to the hearts of children and Muslim families","am":"የድሆችን እና ተፈላጊዎችን መከራ ማቃለል፣ ልጆችን እና የሙስሊም ቤተሰቦችን ማስደሰት","om":"Hiyyeeyyifi gaaronni dabarsuu fi ilmuu fi maatii Muslimoota gammachiisuu"}', '{"ar":"مجتمع مسلم متكافل تسوده المحبة والرحمة، لا يُترك فيه جائع ولا محروم","en":"A cohesive Muslim community governed by love and mercy, where no one is left hungry or deprived","am":"በፍቅር እና በምሕረት የሚመራ የሙስሊም ማህበረሰብ፣ ድሆች የለሽ","om":"Hawaasa Muslimoota jaalalaa fi rahmaa qabu, hiyyeeyyi hin qabu"}', '[{"ar":"الرحمة","en":"Mercy","am":"ምሕረት","om":"Rahmaa"},{"ar":"الإخاء","en":"Brotherhood","am":"ወንድምነት","om":"Hiriyummaa"},{"ar":"العطاء","en":"Giving","am":"መስጠት","om":"Kenna"},{"ar":"الإخلاص","en":"Sincerity","am":"ቅንነት","om":"Qajeelummaa"}]', '[{"ar":"إطعام الفقراء يومياً","en":"Feed the poor daily","am":"ድሆችን በየቀኑ ማበላሸፍ","om":"Hiyyeeyyii guyyaa guyyaa nyaachisuu"},{"ar":"كفالة الأيتام والأرامل","en":"Sponsor orphans and widows","am":"አይሞቹን እና አርዶችን ማስተዳደር","om":"Abbaa irraa dhabootafi haadha manaa deggamsuu"},{"ar":"نشر الدعوة الإسلامية","en":"Spread Islamic Dawah","am":"የእስላም ዳዋን ማስፋት","om":"Dawaa Islaamaa faca''uu"}]', '2014 م.أ', 'charity', 'charity', 'https://images.pexels.com/photos/6646917/pexels-photo-6646917.jpeg?auto=compress&cs=tinysrgb&w=1600', '{"base":"#0369A1","accent":"#F97316","heart":"#e63946"}', '[{"label":{"ar":"طفل يُطعم يومياً","en":"Children fed daily","am":"በየቀኑ የሚበላ ልጅ","om":"Ilmuu guyyaa guyyaa nyaatamu"},"value":82},{"label":{"ar":"أسرة عادت للإسلام","en":"Families returned to Islam","am":"ወደ እስላም የተመለሰ ቤተሰብ","om":"Maatii gara Islaamaatti deebi''e"},"value":11},{"label":{"ar":"منزل مرمم","en":"Homes renovated","am":"የተሰራ ቤት","om":"Mana fooyya''e"},"value":7}]', '[{"name":{"ar":"وجبة الإفطار اليومية","en":"Daily Breakfast Program","am":"የዕለት ምሳ ፕሮግራም","om":"Piroogiraamii Nyaata Guyyaa"},"icon":"utensils","description":{"ar":"وجبة دافئة كل صباح لـ ٨٢ طفلاً من الأطفال المساكين، نبدأ بها يومهم بشبع وابتسامة.","en":"A warm meal every morning for 82 poor children — starting their day with fullness and a smile.","am":"ለ82 ድህከልጆች በየጠዋቱ ዞር ምግብ — ቀናቸውን በጥጥስና በፊጥጐሳ ለመጀመር።","om":"Ilmuu 82 guyyaa guyyaa nyaata ho''aa — guyyaa isaanii fuula gammachuu qabuun jalqabuu."}},{"name":{"ar":"مساعدات رمضان","en":"Ramadan Aid","am":"የረመዳን እርዳታ","om":"Gargaarsa Ramadaanaa"},"icon":"moon","description":{"ar":"سلل رمضانية من المواد الغذائية الأساسية، نفرح بها بيوت المحتاجين في الشهر الفضيل.","en":"Ramadan food baskets with essential staples — bringing joy to the homes of the needy in the blessed month.","am":"የረመዳን የምግብ ቅርጫቶች ከመሠረታዊ እቃዎች ጋር — የተፈላጊዎችን ቤት በቡርኩ ወር ማስደሰት።","om":"Qofee nyaata Ramadaanaa — mana hiyyeeyyii ji''a bareedaa keessatti gammachuu fiduu."}},{"name":{"ar":"وجبات العيد والأضاحي","en":"Eid Meals & Qurbani","am":"የኢድ ምሳ እና ቅባን","om":"Nyaata Iidiifi Qurbanaa"},"icon":"gift","description":{"ar":"لحم الأضاحي ووجبات العيد للأسر المحتاجة، حتى يفرح الجميع في يوم الفرح.","en":"Qurbani meat and Eid meals for needy families — so everyone rejoices on the day of joy.","am":"የቅባን ሥጋና የኢድ ምግቦች ለተፈላጊ ቤተሰቦች — ሁሉም በየዓዋጮቹ ቀን ይደሰት ዘንድ።","om":"Foon Qurbanaa fi nyaata Iidaa maatii hiyyeeyyiif — hundi guyyaa gammachuu gammachuu."}},{"name":{"ar":"ملابس العيد","en":"Eid Clothing","am":"የኢድ ልብሶች","om":"Uffata Iidaa"},"icon":"shirt","description":{"ar":"كسوة العيد للأطفال والأسر المحتاجة، لنرى الفرح في كل وجه في يوم العيد.","en":"Eid clothing for children and needy families — so we see joy on every face on Eid day.","am":"ለልጆችና ለተፈላጊ ቤተሰቦች የኢድ ልብስ — በኢድ ቀን ፊት ሁሉ ላይ ደስታ ለማየት።","om":"Uffata Iidaa ilmaafi maatii hiyyeeyyii — guyyaa Iidaa fuula hunda irratti gammachuu arguu."}},{"name":{"ar":"مواد العودة للمدارس","en":"Back-to-School Materials","am":"የትምህርት ቤት ተመለሻ ቁሶች","om":"Maaloota Deebii Barumsaa"},"icon":"backpack","description":{"ar":"حقائب مدرسية وقرطاسية للأطفال المحتاجين، ندعمهم ليواصلوا تعليمهم بثقة.","en":"School bags and stationery for needy children — supporting them to continue their education with confidence.","am":"ለተፈላጊ ልጆች የትምህርት ቤት ቦርሳና የጽሑፍ ቁሶች — ትምህርታቸውን በመተማመን ለመቀጠል ርድኦ።","om":"Kofaa barumsaa fi meeshaa ilmaan hiyyeeyyii — barumsa isaanii ofii amanuu itti fufu deggamsuu."}},{"name":{"ar":"الدعوة الإسلامية","en":"Islamic Dawah","am":"የእስላም ዳዋ","om":"Dawaa Islaamaa"},"icon":"megaphone","description":{"ar":"جهود دعوية بالحكمة والموعظة الحسنة، عاد منها ١١ أسرة إلى الإسلام بفضل الله.","en":"Dawah efforts with wisdom and beautiful preaching — by Allah''s grace, 11 families have returned to Islam.","am":"በጥበብና በቅን ማስተማር የተደረጉ የዳዋ ጥረናዎች — በአላህ ቸርነት 11 ቤተሰብ ወደ እስላም ተመልሰዋል።","om":"Dawaa ogummaa fi gorsa bareedaa — 11 maatii gara Islaamaatti deebi''an."}},{"name":{"ar":"ترميم المنازل","en":"Home Renovation","am":"የቤት ጥገና","om":"Mana Fooyya''uu"},"icon":"home","description":{"ar":"إصلاح وترميم بيوت الأسر المحتاجة، نعيد إليها الأمان والكرامة.","en":"Repairing and renovating the homes of needy families — restoring safety and dignity to them.","am":"የተፈላጊ ቤተሰቦች ቤት ማስተካከልና ማስፈራፈር — ደህንነትንና ክብርን መመለስ።","om":"Mana maatii hiyyeeyyii sirreessuu fi fooyya''uu — nagaa fi ulfina isaanii deebisuu."}}]', 'https://t.me/daralquran_charity', '-1001234567893', 'closed', '[{"name":"fullName","label":{"ar":"الاسم الكامل","en":"Full Name","am":"ሙሉ ስም","om":"Maqaa guddaa"},"type":"text","required":true},{"name":"phone","label":{"ar":"رقم الهاتف","en":"Phone Number","am":"ስልክ ቁጥር","om":"Lakkoofsa bilbila"},"type":"tel","required":true},{"name":"familySize","label":{"ar":"عدد أفراد الأسرة","en":"Family Size","am":"የቤተሰብ ብዛት","om":"Lakkoofsa maatii"},"type":"number","required":true},{"name":"aidType","label":{"ar":"نوع المساعدة المطلوبة","en":"Type of Aid Needed","am":"የፈለገው የእርዳታ አይነት","om":"Gosa gargaarsa barbaadamu"},"type":"select","required":true,"options":[{"ar":"إطعام","en":"Food","am":"ምግብ","om":"Nyaata"},{"ar":"كفالة يتيم","en":"Orphan Sponsorship","am":"የአይማ ስፖንሰርነት","om":"Deggamsa abbaa irraa dhabaa"},{"ar":"ملابس","en":"Clothing","am":"ልብስ","om":"Uffata"},{"ar":"مواد مدرسية","en":"School Supplies","am":"የትምህርት ቤት እቃዎች","om":"Maaloota barumsaa"},{"ar":"ترميم منزل","en":"Home Renovation","am":"የቤት ጥገና","om":"Mana fooyyuu"}]},{"name":"address","label":{"ar":"العنوان","en":"Address","am":"አድራሻ","om":"Teessoo"},"type":"text","required":false},{"name":"notes","label":{"ar":"ملاحظات","en":"Notes","am":"ማስታወሻዎች","om":"Gabaaboo"},"type":"textarea","required":false}]', '{"ar":"الشروط: أن تكون الأسرة مسلمة ومحتاجة فعلاً، تقديم ما يثبت الحالة (شهادة فقر أو توصية من الإمام أو الجيران)، الالتزام بتوزيع المساعدات على المستحقين. الأولوية للأيتام والأرامل والفقراء.","en":"Requirements: The family must be Muslim and genuinely in need, providing proof of situation (poverty certificate or recommendation from the Imam or neighbors). Priority is given to orphans, widows, and the poor.","am":"ሁኔታዎች፡ ቤተሰቡ ሙስሊምና በእውነት ድህነት ውስጥ መሆን፣ ሁኔታውን የሚያረጋግጥ ማስረጃ ማቅረብ (የድህነት ማረጋገጫ ወይም ከኢማሙ ወይም ከጎረቤቶች የተገኘ ምክር)። ቅድሚያ ለአይሞች፣ ለአርዶች እና ለድሆች ይሰጣል።","om":"Eegumsa: Maatiin Muslimaafi hiyyeessa ta''e, raga haalaa (raga hiyyeessaa ykn gorsa Imaamii ykn hojjettoota) dhihaachuu. Abbaa irraa dhaboota, haadha manaa fi hiyyeeyyiif fuuldura kennamu."}')
